js="\n(()=>{'use strict';\nconst $=id=>document.getElementById(id),slides=[...document.querySelectorAll('.slide')];let current=0;\nlet data;try{data=JSON.parse($('benchmark-data').textContent)}catch{data={}}\nconst values=data.slideValues||{};\ndocument.querySelectorAll('[data-value]').forEach(e=>{if(values[e.dataset.value]!==undefined)e.textContent=values[e.dataset.value]});\nconst numeric=data.slideNumbers||{};\ndocument.querySelectorAll('[data-chart]').forEach(chart=>{const rows=[...chart.querySelectorAll('[data-bar]')],max=Math.max(1,...rows.map(r=>numeric[r.dataset.bar]||0));rows.forEach(r=>{r.querySelector('i b').style.width=`${100*(numeric[r.dataset.bar]||0)/max}%`;});});\nfunction resize(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1600,(innerHeight-56)/900))}\nfunction notes(){const s=slides[current];$('notes-title').textContent=`${current+1}. ${s.dataset.title}`;$('notes-time').textContent=s.dataset.time;$('notes-content').replaceChildren(s.querySelector('template.notes').content.cloneNode(true));$('notes-content').innerHTML=$('notes-content').innerHTML.replace(/\\{\\{([^}]+)\\}\\}/g,(whole,key)=>data.noteValues?.[key]??'—');const key=s.dataset.experiment;if(key&&data.experimentNotes?.[key]){const p=document.createElement('p');p.textContent=data.experimentNotes[key];$('notes-content').append(p)}}\nfunction go(n,hash=true){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',i===current?'false':'true')});$('counter').textContent=`${String(current+1).padStart(2,'0')} / ${slides.length}`;$('previous').disabled=current===0;$('next').disabled=current===slides.length-1;document.title=`${current+1}. ${slides[current].dataset.title} · NSLondon`;$('announcement').textContent=`Slide ${current+1} of ${slides.length}`;notes();if(hash)history.replaceState(null,'',`#slide-${current+1}`)}\nfunction fromHash(){const n=Number(location.hash.replace(/^#(?:slide-)?/,''));return Number.isFinite(n)&&n>0?n-1:0}\nfunction drawer(id,force){const target=$(id),open=typeof force==='boolean'?force:!target.classList.contains('open');document.querySelectorAll('.drawer').forEach(e=>e.classList.remove('open'));$('notes-button').setAttribute('aria-expanded','false');$('sources-button').setAttribute('aria-expanded','false');if(open){target.classList.add('open');$(id==='notes-drawer'?'notes-button':'sources-button').setAttribute('aria-expanded','true')}}\nasync function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}}\n$('previous').onclick=()=>go(current-1);$('next').onclick=()=>go(current+1);$('notes-button').onclick=()=>drawer('notes-drawer');$('sources-button').onclick=()=>drawer('sources-drawer');$('fullscreen').onclick=fullscreen;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>drawer(b.dataset.close,false));\ndocument.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(['ArrowRight','PageDown'].includes(e.key)||(e.key===' '&&e.target.tagName!=='BUTTON')){e.preventDefault();go(current+1)}else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(current-1)}else if(e.key==='Home'){e.preventDefault();go(0)}else if(e.key==='End'){e.preventDefault();go(slides.length-1)}else if(['n'].includes(e.key.toLowerCase()))drawer('notes-drawer');else if(['f'].includes(e.key.toLowerCase()))fullscreen();else if(e.key==='Escape')drawer('notes-drawer',false)});\nconst sources=new Map();slides.forEach(s=>s.querySelector('template.notes').content.querySelectorAll('a').forEach(a=>sources.set(a.href,a.textContent)));sources.forEach((label,url)=>{const li=document.createElement('li'),a=document.createElement('a');a.href=url;a.textContent=label;a.target='_blank';a.rel='noopener noreferrer';li.append(a);$('sources-list').append(li)});\naddEventListener('resize',resize);addEventListener('hashchange',()=>go(fromHash(),false));resize();go(fromHash());\n})();\n"
notespath=ROOT/'presentation-notes.json'
notes=json.loads(notespath.read_text()) if notespath.exists() else {}
notesrows=notes.get('slides',[]) if isinstance(notes,dict) else notes
byid={int(x.get('number',x.get('id',x.get('slide',i+1)))):x for i,x in enumerate(notesrows)}
durations=[20,10,40,35,25,35,25,45,50,50,40,40,35,45,45,30,45,35,30,60,50,10,50,50,55,5,45]
time=0;sections=[]
for n,s in enumerate(slides,1):
    row=byid.get(n,{})
    duration=row.get('durationSeconds',durations[n-1]);start=time;time+=duration
    stamp=lambda x:f'{int(x)//60}:{int(x)%60:02d}'
    timing=f'{stamp(start)}–{stamp(time)}'
    note=row.get('speakerNotes',s['note'])
    if isinstance(note,list):note=''.join(f'<p>{html.escape(str(x))}</p>' for x in note)
    elif '<p>' not in str(note):note=f'<p>{html.escape(str(note))}</p>'
    if row.get('transition'):note+=f'<p>{html.escape(row["transition"])}</p>'
    links=''
    for source in row.get('sourceURLs',[]):
        if isinstance(source,str):url=source;label=source
        else:url=source.get('url','');label=source.get('title',source.get('label',url))
        links+=f'<p><a href="{html.escape(url)}">{html.escape(label)}</a></p>'
    experiment={11:'expression',14:'cache',18:'manifest',21:'packages',22:'combined'}.get(n,'')
    sections.append(f'<section class="slide {s["cls"]} {"active" if n==1 else ""}" id="slide-{n}" data-title="{html.escape(s["title"])}" data-time="{timing}" data-experiment="{experiment}"><div class="section-label">{html.escape(s["section"])}</div>{s["body"]}<template class="notes">{note}{links}</template></section>')
data=json.loads((ROOT/'presentation-data.json').read_text())
if not data.get('slideValues'):data={'status':'pending','slideValues':{},'slideNumbers':{}}
encoded=json.dumps(data,ensure_ascii=False,indent=2).replace('</','<\\/')
out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Make your build time quicker · NSLondon</title><style>{css}</style></head><body><main class="frame" aria-label="NSLondon presentation">{''.join(sections)}</main><nav class="controls" aria-label="Presentation controls"><div class="controls-group"><button id="notes-button" aria-controls="notes-drawer" aria-expanded="false">Notes <span class="hint">N</span></button><button id="sources-button" aria-controls="sources-drawer" aria-expanded="false">Sources</button></div><div class="controls-group arrows"><button id="previous" aria-label="Previous slide">←</button><span class="counter" id="counter">01 / 27</span><button id="next" aria-label="Next slide">→</button></div><div class="controls-group"><span class="hint">← → &nbsp; Home / End</span><button id="fullscreen">Fullscreen <span class="hint">F</span></button></div></nav><aside id="notes-drawer" class="drawer" aria-label="Speaker notes"><div class="drawer-header"><div><h2 id="notes-title"></h2><p class="timing" id="notes-time"></p></div><button data-close="notes-drawer" aria-label="Close notes">×</button></div><div id="notes-content"></div></aside><aside id="sources-drawer" class="drawer" aria-label="Sources"><div class="drawer-header"><h2>Sources</h2><button data-close="sources-drawer" aria-label="Close sources">×</button></div><ol id="sources-list"></ol></aside><div id="announcement" class="sr-only" aria-live="polite"></div><script type="application/json" id="benchmark-data">{encoded}</script><script>{js}</script></body></html>'''
(ROOT/'presentation.html').write_text(out)
(ROOT/'index.html').write_text(out)
print(len(slides),'slides',time,'seconds')
